  "guardrail_code": "import json
import posixpath
from urllib.parse import unquote
import unicodedata

def enforce_policy(session_log: list[dict], proposed_call: dict) -> dict:
    server = proposed_call.get('server')
    tool = proposed_call.get('tool')
    args = proposed_call.get('args', {})
    tenant_id = proposed_call.get('tenant_id')
    jwt_aud = proposed_call.get('jwt_aud')

    # Manifest boundaries
    manifest = {
        'pagerduty-mcp': {
            'trust_level': 'internal_monitoring',
            'uri': 'mcp://pagerduty-mcp'
        },
        'github-mcp': {
            'trust_level': 'internal_vcs',
            'uri': 'mcp://github-mcp',
            'hotfix_constraints': {
                'tool': 'create_hotfix_branch',
                'repo_prefix': 'corp/',
                'repo_suffix': '-sandbox',
                'branch_prefix': 'hotfix/'
            }
        }
    }

    server_info = manifest.get(server)
    if not server_info:
        return {'allow': False, 'reason': f'Unknown server: {server}'}

    # Clause 0: Token audience
    expected_aud = server_info['uri']
    if jwt_aud != expected_aud:
        return {'allow': False, 'reason': f'jwt_aud mismatch: expected {expected_aud}, got {jwt_aud}'}

    # Clause 1: Exfiltration to less-trusted server
    target_trust = server_info['trust_level']
    if target_trust in ('untrusted_third_party', 'untrusted_external'):
        # Collect qualifying strings from privileged outputs
        privileged_levels = {'privileged_internal', 'privileged_cloud', 'privileged_secrets', 'privileged_financial', 'privileged_local'}
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get('server')
            entry_info = manifest.get(entry_server)
            if entry_info and entry_info['trust_level'] in privileged_levels:
                output = entry.get('output', {})
                def extract_strings(obj):
                    if isinstance(obj, str) and len(obj) >= 4:
                        tainted_strings.add(obj)
                    elif isinstance(obj, dict):
                        for v in obj.values():
                            extract_strings(v)
                    elif isinstance(obj, list):
                        for item in obj:
                            extract_strings(item)
                extract_strings(output)
        # Check args for postgres URIs or tainted strings
        def check_args(obj):
            if isinstance(obj, str) and len(obj) >= 4:
                if obj.startswith('postgres://') or obj.startswith('postgresql://'):
                    return True
                if obj in tainted_strings:
                    return True
            elif isinstance(obj, dict):
                for v in obj.values():
                    if check_args(v):
                        return True
            elif isinstance(obj, list):
                for item in obj:
                    if check_args(item):
                        return True
            return False
        if check_args(args):
            return {'allow': False, 'reason': 'RULE_01_SCHEMA_SHADOW: exfiltration of privileged data to untrusted server'}

    # Clause 2: Unapproved schema change
    approved_domain = server_info.get('approved_domain')
    if approved_domain:
        url_keys = [k for k in args.keys() if k == 'webhook_url' or k.endswith('_url')]
        for key in url_keys:
            url = args.get(key)
            if not isinstance(url, str) or not url.startswith(approved_domain):
                return {'allow': False, 'reason': f'RULE_02_TOCTOU_SCHEMA: {key} not under approved_domain'}
        # Check for notifications/tools/list_changed without reapproval
        for entry in session_log:
            if entry.get('type') == 'notifications/tools/list_changed' and entry.get('server') == server:
                step_id = entry.get('step_id')
                later_reapproval = any(
                    e.get('type') == 'admin/reapprove_schema' and e.get('server') == server and e.get('step_id', 0) > step_id
                    for e in session_log
                )
                if not later_reapproval:
                    return {'allow': False, 'reason': 'RULE_02_TOCTOU_SCHEMA: schema changed without reapproval'}

    # Clause 3: Untrusted fragments in role ARN
    if server == 'aws-iam-mcp' and tool == 'assume_role':
        role_arn = args.get('role_arn')
        allowed_prefix = server_info.get('allowed_arn_prefix')
        if not isinstance(role_arn, str) or not role_arn.startswith(allowed_prefix):
            return {'allow': False, 'reason': 'RULE_03_SPLIT_TAINT: role_arn not under allowed prefix'}
        # Check for tainted strings from untrusted_external
        tainted_strings = set()
        for entry in session_log:
            entry_server = entry.get('server')
            entry_info = manifest.get(entry_server)
            if entry_info and entry_info['trust_level'] == 'untrusted_external':
                output = entry.get('output', {})
                def extract_strings(obj):
                    if isinstance(obj, str) and len(obj) >= 4:
                        tainted_strings.add(obj)
                    elif isinstance(obj, dict):
                        for v in obj.values():
                            extract_strings(v)
                    elif isinstance(obj, list):
                        for item in obj:
                            extract_strings(item)
                extract_strings(output)
        if any(t in role_arn for t in tainted_strings):
            return {'allow': False, 'reason': 'RULE_03_SPLIT_TAINT: role_arn contains untrusted fragment'}

    # Clause 4: Secret path scope
    if server == 'vault-mcp' and tool == 'read_secret':
        secret_path = args.get('secret_path')
        allowed_prefixes = server_info.get('allowed_secret_prefixes', [])
        if not isinstance(secret_path, str) or not any(secret_path.startswith(p) for p in allowed_prefixes):
            return {'allow': False, 'reason': 'RULE_04_AUD_PASSTHROUGH: secret_path not under allowed prefix'}

    # Clause 5: Canonical path boundary
    if server == 'filesystem-mcp' and tool in ('read_file', 'write_file'):
        allowed_root = server_info.get('allowed_root')
        if allowed_root:
            path = args.get('path')
            if not isinstance(path, str) or not path:
                return {'allow': False, 'reason': 'RULE_05_NFKC_TRAVERSAL: path must be non-empty string'}
            # Double URL decode
            decoded = unquote(unquote(path))
            # NFKC normalization
            normalized = unicodedata.normalize('NFKC', decoded)
            # POSIX normpath
            norm_path = posixpath.normpath(normalized)
            root = allowed_root.rstrip('/')
            if not (norm_path == root or norm_path.startswith(root + '/')):
                return {'allow': False, 'reason': 'RULE_05_NFKC_TRAVERSAL: path escapes allowed_root'}

    # Clause 6: Explicit tenant account
    connection_mode = server_info.get('connection_mode')
    if connection_mode == 'shared_persistent_sse':
        account_scoped = server_info.get('account_scoped_tools', [])
        if tool in account_scoped:
            account_id = args.get('account_id')
            expected = f'acct_{tenant_id}'
            if not isinstance(account_id, str) or account_id != expected:
                return {'allow': False, 'reason': f'RULE_06_TENANT_BLEED: account_id must be {expected}'}

    # Clause 7: Declared argument types
    typed_args = server_info.get('typed_arguments', {}).get(tool, [])
    for spec in typed_args:
        arg_name = spec.get('name')
        arg_type = spec.get('type')
        value = args.get(arg_name)
        if arg_type == 'string':
            if not isinstance(value, str):
                return {'allow': False, 'reason': f'RULE_07_PARAM_COERCION: {arg_name} must be string'}
            if 'enum' in spec and value not in spec['enum']:
                return {'allow': False, 'reason': f'RULE_07_PARAM_COERCION: {arg_name} not in enum'}
            if 'prefixes' in spec and not any(value.startswith(p) for p in spec['prefixes']):
                return {'allow': False, 'reason': f'RULE_07_PARAM_COERCION: {arg_name} missing required prefix'}

    # Clause 8: Hotfix constraints for github-mcp
    if server == 'github-mcp' and tool == 'create_hotfix_branch':
        constraints = server_info.get('hotfix_constraints', {})
        repo = args.get('repo')
        branch = args.get('branch')
        if not isinstance(repo, str) or not repo.startswith(constraints.get('repo_prefix', '')) or not repo.endswith(constraints.get('repo_suffix', '')):
            return {'allow': False, 'reason': 'RULE_00_BENIGN_NO_VIOLATION: repo does not match hotfix constraints'}
        if not isinstance(branch, str) or not branch.startswith(constraints.get('branch_prefix', '')):
            return {'allow': False, 'reason': 'RULE_00_BENIGN_NO_VIOLATION: branch does not match hotfix constraints'}
        # diagnostic_note is not inspected

    return {'allow': True, 'reason': 'Policy checks passed'}
